import{_ as n,I as i,o as l,c as h,j as t,a as r,J as a,a6 as o}from"./chunks/framework.9ylqSDY5.js";const b=JSON.parse('{"title":"Targets of Opportunity","description":"","frontmatter":{"title":"Targets of Opportunity","visibility":"public","audience":"astronomer","tier":"guide","source":"handwritten"},"headers":[],"relativePath":"guides/observing/too-policies.md","filePath":"guides/observing/too-policies.md"}'),d={name:"guides/observing/too-policies.md"};function p(c,e,u,g,f,y){const s=i("ToolShot");return l(),h("div",null,[e[0]||(e[0]=t("h1",{id:"targets-of-opportunity",tabindex:"-1"},[r("Targets of Opportunity "),t("a",{class:"header-anchor",href:"#targets-of-opportunity","aria-label":"Permalink to “Targets of Opportunity”"},"​")],-1)),e[1]||(e[1]=t("p",null,[t("strong",null,"Decide in advance which transients are worth the telescope."),r(" Target of Opportunity (ToO) policies judge each alert as it arrives, and tell you about it or observe it at once.")],-1)),a(s,{tool:"transient-alerts"}),e[2]||(e[2]=o('<h2 id="what-it-is-for" tabindex="-1">What it is for <a class="header-anchor" href="#what-it-is-for" aria-label="Permalink to “What it is for”">​</a></h2><ul><li>Be notified of the alerts your telescope can observe.</li><li>Interrupt the night for the most important ones.</li><li>Know afterwards what became of every alert, and why.</li></ul><p>To browse the transient sky itself, use <a href="./night-studio#transient-sky">Transient Sky</a>.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to “Before you start”">​</a></h2><p>The alerts come from an optional service, set up once by the operator: see <a href="/guides/operating/transient-alerts">Receiving transient alerts</a>. The header of the tool says whether each feed is listening.</p><h2 id="policies-and-series" tabindex="-1">Policies and series <a class="header-anchor" href="#policies-and-series" aria-label="Permalink to “Policies and series”">​</a></h2>',6)),a(s,{tool:"transient-alerts",index:1}),e[3]||(e[3]=o('<p>A <strong>policy</strong> says which alerts matter, from which telescope:</p><table tabindex="0"><thead><tr><th>Part</th><th>What you set</th></tr></thead><tbody><tr><td><strong>Which alerts</strong></td><td>The missions, the largest localization error, and a priority when several policies match. ZTF alerts are only taken by a policy that names them</td></tr><tr><td><strong>Observability</strong></td><td>The Sun below, the target above and the Moon at least at given angles. The telescope&#39;s horizon mask counts when there is one</td></tr><tr><td><strong>Action</strong></td><td><em>Notify</em>, or <em>interrupt</em> with a given series</td></tr><tr><td><strong>Later</strong></td><td>Whether an alert that is not up yet may be observed later in the night, and for how long at least</td></tr></tbody></table><p>A <strong>series</strong> says what the telescope does when a policy interrupts: focus if the focus is stale, centre by plate solving, then take the frames. It can run for a number of frames, for a duration, or for as long as possible. It always ends when the target sets, the Sun rises, the Moon comes too close, safety says NOGO, or the event is retracted.</p><p>Without any policy, alerts are not evaluated.</p><h2 id="when-a-policy-interrupts" tabindex="-1">When a policy interrupts <a class="header-anchor" href="#when-a-policy-interrupts" aria-label="Permalink to “When a policy interrupts”">​</a></h2><ol><li>A dialog announces it, with a 30-second countdown: <strong>Interrupt now</strong> or <strong>Keep observing</strong>. No answer means yes.</li><li>The frame in progress is read out, and what is running is stopped.</li><li>The series takes the telescope. A banner follows it, with a <strong>Stop</strong> button.</li><li>A Night Scheduler sequence that was running resumes when the series ends.</li></ol><p>Interruptions only happen on a setup whose <strong>Interrupts</strong> switch, in the status bar, is on. It is on by default. Switching it off refuses new runs; one already observing goes on.</p><h2 id="verdicts-runs" tabindex="-1">Verdicts &amp; Runs <a class="header-anchor" href="#verdicts-runs" aria-label="Permalink to “Verdicts &amp; Runs”">​</a></h2><p>Every alert is listed with its verdict and the policy that gave it. From there, dismiss an alert, or press <strong>Observe now</strong> to run the series yourself. Beside it, the runs: what was triggered, how many frames were taken, and how it ended.</p><h2 id="custom-sources" tabindex="-1">Custom sources <a class="header-anchor" href="#custom-sources" aria-label="Permalink to “Custom sources”">​</a></h2><p>Feeds other than GCN can push their own alerts. Create a source, and hand its address and token to the relay that sends the events. Only admins see the token, and only admins and owners edit policies.</p>',11))])}const w=n(d,[["render",p]]);export{b as __pageData,w as default};
